import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static int n;
    static long budget;
    static long[] comp, stock, cost;

    // Cheapest purchase for x units, stopping as soon as it exceeds the budget.
    static boolean ok(long x) {
        long spent = 0;
        for (int i = 0; i < n; i++) {
            long shortfall = x * comp[i] - stock[i];
            if (shortfall <= 0) continue;
            if (shortfall > budget) return false;
            spent += shortfall * cost[i];
            if (spent > budget) return false;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        n = nextInt();
        budget = nextLong();
        comp = new long[n];
        stock = new long[n];
        cost = new long[n];
        for (int i = 0; i < n; i++) comp[i] = nextLong();
        for (int i = 0; i < n; i++) stock[i] = nextLong();
        for (int i = 0; i < n; i++) cost[i] = nextLong();
        long lo = 0, hi = 1;
        while (ok(hi)) hi *= 2;
        while (lo + 1 < hi) {
            long mid = (lo + hi) / 2;
            if (ok(mid)) lo = mid;
            else hi = mid;
        }
        System.out.println(lo);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

var n int
var budget int64
var comp, stock, cost []int64

// Cheapest purchase for x units, stopping as soon as it exceeds the budget.
func ok(x int64) bool {
	var spent int64
	for i := 0; i < n; i++ {
		shortfall := x*comp[i] - stock[i]
		if shortfall <= 0 {
			continue
		}
		if shortfall > budget {
			return false
		}
		spent += shortfall * cost[i]
		if spent > budget {
			return false
		}
	}
	return true
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n = int(nextInt())
	budget = nextInt()
	comp, stock, cost = make([]int64, n), make([]int64, n), make([]int64, n)
	for _, arr := range [][]int64{comp, stock, cost} {
		for i := range arr {
			arr[i] = nextInt()
		}
	}
	lo, hi := int64(0), int64(1)
	for ok(hi) {
		hi *= 2
	}
	for lo+1 < hi {
		mid := (lo + hi) / 2
		if ok(mid) {
			lo = mid
		} else {
			hi = mid
		}
	}
	fmt.Println(lo)
